/**
 * Schema-drift gate for the PostgreSQL full-text search vector.
 *
 * The words.search_vector column (tsvector, GENERATED ALWAYS AS) and the
 * idx_words_search GIN index are regenerated by drizzle-kit from src/db/schema.ts.
 * A careless edit to the search expression or index would silently change the
 * generated migration and break full-text search in production. This gate
 * regenerates the schema into a throwaway directory, extracts those two
 * definitions, and fails closed if they drift from the authoritative contract.
 *
 * It also carries the release migration-chain guards (0047–0050 incident):
 * `_journal.json` inspection (strictly increasing `when`, complete entries,
 * no orphan tag/file in either direction) plus a generate no-op proof
 * against a throwaway copy of drizzle-release. Rationale: the drizzle migrator
 * reads `lastDbMigration` once (highest created_at) and filters with a strict
 * `<` (node_modules/drizzle-orm/pg-core/dialect.js:56-71), so tied `when`
 * values silently skip every tied migration on incremental databases; and a
 * missing terminal snapshot makes `db:generate` replay applied migrations as a
 * brand-new pseudo migration.
 *
 * Run: npm run db:schema:drift   (requires DATABASE_URL to be set; the value is
 * only read by drizzle-kit config loading — `generate` does not connect to a DB)
 */
import { spawnSync } from "node:child_process";
import { cpSync, mkdirSync, mkdtempSync, rmSync, symlinkSync, unlinkSync, writeFileSync, readdirSync, readFileSync, existsSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";

const scriptDir = path.dirname(fileURLToPath(import.meta.url));
const projectRoot = path.resolve(scriptDir, "..");

/** Authoritative generated SQL for the words.search_vector column. */
export const AUTHORITATIVE_SEARCH_VECTOR =
  `"search_vector" "tsvector" GENERATED ALWAYS AS (to_tsvector('english'::regconfig, ((((((((((COALESCE(lemma, ''::text) || ' '::text) || COALESCE(title, ''::text)) || ' '::text) || COALESCE(short_definition, ''::text)) || ' '::text) || COALESCE(definition_md, ''::text)) || ' '::text) || COALESCE((metadata ->> 'semantic_field'::text), ''::text)) || ' '::text) || COALESCE((metadata ->> 'word_freq'::text), ''::text))))) STORED`;

/** Authoritative generated SQL for the words.idx_words_search GIN index. */
export const AUTHORITATIVE_SEARCH_INDEX =
  `CREATE INDEX "idx_words_search" ON "words" USING gin ("search_vector" tsvector_ops)`;

/** Authoritative generated RLS contracts for owner-scoped rows. */
export const AUTHORITATIVE_L2_PROGRESS_RLS =
  `ALTER TABLE "user_word_l2_progress" ENABLE ROW LEVEL SECURITY`;
export const AUTHORITATIVE_L2_PROGRESS_POLICY =
  `CREATE POLICY "user_word_l2_progress_own_all" ON "user_word_l2_progress" AS PERMISSIVE FOR ALL TO public USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id))`;
export const AUTHORITATIVE_PROFILES_SELECT_POLICY =
  `CREATE POLICY "profiles_select_own" ON "profiles" AS PERMISSIVE FOR SELECT TO public USING ((auth.uid() = id))`;
export const AUTHORITATIVE_HIGHLIGHTS_RLS =
  `ALTER TABLE "word_highlights" ENABLE ROW LEVEL SECURITY`;
export const AUTHORITATIVE_HIGHLIGHTS_POLICY =
  `CREATE POLICY "word_highlights_own_all" ON "word_highlights" AS PERMISSIVE FOR ALL TO public USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id))`;
export const AUTHORITATIVE_ANNOTATIONS_RLS =
  `ALTER TABLE "word_annotations" ENABLE ROW LEVEL SECURITY`;
export const AUTHORITATIVE_ANNOTATIONS_POLICY =
  `CREATE POLICY "word_annotations_own_all" ON "word_annotations" AS PERMISSIVE FOR ALL TO public USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id))`;

/**
 * 0039（N1 学习笔记）五张表的 owner RLS 契约——regenerate 时逐条比对，
 * 防止保存/引用路径的隔离面被静默改动。
 */
